function history(){if(!applied)return;const view=canvas('history');if(!view)return;const {c,w,h}=view,channel=channels[$('forceAxis').value],window=channel.tyre?applied.scenario.observationWindow:null;const frames=window?applied.frames.filter(f=>{const tick=Math.round(f.time/applied.scenario.motion.dt);return tick>=window.startTick&&tick<=window.endTick;}):applied.frames;c.font='11px system-ui';if(!frames.length){c.fillStyle='#9aabb7';c.fillText('No accepted observation-window samples.',8,24);return;}const xmin=frames[0].time,xspan=frames.at(-1).time-xmin||1;
 for(let k=0;k<2;k++){const top=k*h/2+22,bottom=(k+1)*h/2-12,vals=frames.map(f=>channel.value(f,k)),lo=Math.min(0,...vals)<0?Math.min(-channel.minimum,...vals):0,hi=Math.max(channel.minimum,...vals),x=t=>42+(w-54)*(t-xmin)/xspan,z=v=>bottom-(bottom-top)*(v-lo)/(hi-lo);c.fillStyle='#9aabb7';c.fillText((channel.rider?(k?'Feet ':'Hands '):(k?'Rear ':'Front '))+channel.label,8,top-7);c.fillText(hi.toPrecision(3),4,top+8);if(lo<0)c.fillText(lo.toPrecision(3),4,bottom);c.strokeStyle='#344654';c.beginPath();c.moveTo(42,z(0));c.lineTo(w-12,z(0));c.stroke();c.strokeStyle=k?'#f2b373':'#84c8ff';c.beginPath();frames.forEach((f,i)=>i?c.lineTo(x(f.time),z(vals[i])):c.moveTo(x(f.time),z(vals[i])));c.stroke();const selected=applied.frames[index].time;if(selected>=xmin&&selected<=frames.at(-1).time){c.strokeStyle='#c2a3ff';c.beginPath();c.moveTo(x(selected),top);c.lineTo(x(selected),bottom);c.stroke();}}
}
